import { chmodSync, existsSync, mkdirSync, readFileSync, renameSync, rmSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import type { KitConfig } from '../../config/schema'
import type { EnvSchema, EnvValues } from './schema'

/**
 * Outputs rendered from `.env` (ported from WhaleSay `_lib/env-master.ts` and brewd `lib/env.ts`).
 *
 * `env.outputs[path] = { pick?, rename? }`:
 * - `pick`: source keys written under their own name.
 * - `rename`: `{ OUTPUT_NAME: 'SOURCE_KEY' }`, e.g. admin binds INTERNAL_ADMIN_SECRET as X_INTERNAL_SECRET.
 * - neither: every schema key.
 * Lines follow pick order, then rename order. Files are `.dev.vars` format, written atomically at 0600.
 * A blank value renders as a commented `# KEY=` so the file documents the key and dev servers still boot.
 */

export const GENERATED_BANNER =
  '# Generated by `kit env sync` from .env. Edit .env and re-run; do not edit by hand.\n'

export interface OutputLine {
  /** Name in the output file. */
  name: string
  /** Key in `.env`. */
  source: string
}

export interface Output {
  /** Repo-relative path from config. */
  path: string
  lines: OutputLine[]
}

export function outputs(config: KitConfig, schema: EnvSchema): Output[] {
  return Object.entries(config.env?.outputs ?? {}).map(([path, o]) => {
    const lines: OutputLine[] = []
    for (const k of o.pick ?? []) lines.push({ name: k, source: k })
    for (const [name, source] of Object.entries(o.rename ?? {})) lines.push({ name, source })
    if (!o.pick && !o.rename) for (const k of schema.keys) lines.push({ name: k.name, source: k.name })
    return { path, lines }
  })
}

/** One `.dev.vars` line. Multi-line values (a PEM) are double-quoted with `\n`, which dotenv expands. */
function line(name: string, value: string | undefined): string {
  if (value === undefined || value === '') return `# ${name}=\n`
  if (/[\r\n]/.test(value)) return `${name}="${value.replace(/\r?\n/g, '\\n')}"\n`
  return `${name}=${value}\n`
}

/** Render an output. Pure. */
export function render(output: Output, values: EnvValues): string {
  let out = GENERATED_BANNER
  for (const l of output.lines) out += line(l.name, values[l.source])
  return out
}

/** Parse a rendered (or any dotenv) file into name → value; `# KEY=` placeholders read as ''. */
export function parseDotenv(text: string): Record<string, string> {
  const out: Record<string, string> = {}
  for (const raw of text.split('\n')) {
    const placeholder = /^#\s*([A-Za-z_][A-Za-z0-9_]*)=\s*$/.exec(raw.trim())
    if (placeholder) {
      out[placeholder[1]!] = ''
      continue
    }
    const m = /^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$/.exec(raw)
    if (!m) continue
    out[m[1]!] = m[2]!.replace(/^(['"])(.*)\1$/, '$2')
  }
  return out
}

export interface KeyDiff {
  added: string[]
  updated: string[]
  removed: string[]
}

/** Which names differ between two files. Names only; values never leave this function. */
export function diffKeys(prev: string | null, next: string): KeyDiff {
  const a = prev === null ? {} : parseDotenv(prev)
  const b = parseDotenv(next)
  return {
    added: Object.keys(b).filter((k) => !(k in a)),
    updated: Object.keys(b).filter((k) => k in a && a[k] !== b[k]),
    removed: Object.keys(a).filter((k) => !(k in b)),
  }
}

export interface WriteResult extends KeyDiff {
  path: string
  changed: boolean
}

/** Write via a temp file and rename, so a reader never sees half a file. */
export function writeAtomic(file: string, contents: string): void {
  mkdirSync(dirname(file), { recursive: true })
  const tmp = `${file}.${process.pid}.tmp`
  try {
    writeFileSync(tmp, contents, { mode: 0o600 })
    chmodSync(tmp, 0o600)
    renameSync(tmp, file)
  } finally {
    rmSync(tmp, { force: true })
  }
}

const read = (file: string) => (existsSync(file) ? readFileSync(file, 'utf8') : null)

/** Render and write every output; unchanged files are left alone (mode healed to 0600). */
export function writeOutputs(root: string, list: Output[], values: EnvValues, dryRun = false): WriteResult[] {
  return list.map((o) => {
    const file = resolve(root, o.path)
    const next = render(o, values)
    const prev = read(file)
    const diff = diffKeys(prev, next)
    if (prev === next) {
      if (!dryRun) chmodSync(file, 0o600)
      return { path: o.path, changed: false, ...diff }
    }
    if (!dryRun) writeAtomic(file, next)
    return { path: o.path, changed: true, ...diff }
  })
}

export interface Drift extends KeyDiff {
  path: string
  reason: 'missing' | 'stale'
}

export function checkOutputs(root: string, list: Output[], values: EnvValues): Drift[] {
  const out: Drift[] = []
  for (const o of list) {
    const prev = read(resolve(root, o.path))
    const next = render(o, values)
    if (prev === null) out.push({ path: o.path, reason: 'missing', ...diffKeys(null, next) })
    else if (prev !== next) out.push({ path: o.path, reason: 'stale', ...diffKeys(prev, next) })
  }
  return out
}
